/**
 * Offline support.
 *  - The service worker (Workbox, generated by vite-plugin-pwa) precaches the core:
 *    HTML, every JS chunk (all lessons), CSS, fonts (incl. KaTeX), icons.
 *  - Python (Pyodide + numpy/scipy/sympy/matplotlib, ~50 MB) lives in its own cache.
 *    It fills up automatically as packages are used, or all at once with
 *    "Download everything for offline" (Settings), which shows progress.
 */
import { PYODIDE_CACHE } from '../py/version';

export interface Manifest {
  version: string;
  packages: string[];
  files: { name: string; size: number }[];
}

type Listener = () => void;
const listeners = new Set<Listener>();
export const offlineState = {
  online: typeof navigator === 'undefined' ? true : navigator.onLine,
  swActive: false,
  coreReady: false,
};
function emit() {
  listeners.forEach((l) => l());
}
export function onOfflineChange(l: Listener) {
  listeners.add(l);
  return () => void listeners.delete(l);
}

const base = () => import.meta.env.BASE_URL;

export function registerOffline() {
  if (typeof window === 'undefined') return;
  window.addEventListener('online', () => {
    offlineState.online = true;
    emit();
  });
  window.addEventListener('offline', () => {
    offlineState.online = false;
    emit();
  });
  if (!('serviceWorker' in navigator) || import.meta.env.DEV) return;
  import('virtual:pwa-register')
    .then(({ registerSW }) => {
      registerSW({
        immediate: true,
        onOfflineReady() {
          offlineState.coreReady = true;
          emit();
        },
        onRegisteredSW() {
          void checkCore();
        },
      });
    })
    .catch(() => undefined);
  navigator.serviceWorker.ready.then(() => {
    offlineState.swActive = true;
    void checkCore();
  });
}

/** Core is ready when the Workbox precache holds our index.html. */
export async function checkCore(): Promise<boolean> {
  if (!('caches' in window)) return false;
  try {
    const keys = await caches.keys();
    for (const k of keys) {
      if (!k.includes('precache')) continue;
      const c = await caches.open(k);
      const reqs = await c.keys();
      if (reqs.some((r) => /index\.html/.test(r.url))) {
        offlineState.coreReady = true;
        emit();
        return true;
      }
    }
  } catch {
    /* ignore */
  }
  return offlineState.coreReady;
}

export async function loadManifest(): Promise<Manifest | null> {
  try {
    const r = await fetch(`${base()}pyodide/manifest.json`, { cache: 'no-cache' });
    if (!r.ok) throw new Error(String(r.status));
    const m = (await r.json()) as Manifest;
    // keep the manifest itself available offline
    if ('caches' in window) {
      const c = await caches.open(PYODIDE_CACHE);
      await c.put(`${base()}pyodide/manifest.json`, new Response(JSON.stringify(m), { headers: { 'content-type': 'application/json' } }));
    }
    return m;
  } catch {
    if (!('caches' in window)) return null;
    const c = await caches.open(PYODIDE_CACHE);
    const hit = await c.match(`${base()}pyodide/manifest.json`);
    return hit ? ((await hit.json()) as Manifest) : null;
  }
}

/** How much of Python is in the offline cache. */
export async function pythonCacheStatus(): Promise<{ have: number; total: number; bytes: number; totalBytes: number }> {
  const m = await loadManifest();
  if (!m || !('caches' in window)) return { have: 0, total: m?.files.length ?? 0, bytes: 0, totalBytes: 0 };
  const c = await caches.open(PYODIDE_CACHE);
  let have = 0, bytes = 0;
  for (const f of m.files) {
    if (await c.match(`${base()}pyodide/${f.name}`)) {
      have++;
      bytes += f.size;
    }
  }
  return { have, total: m.files.length, bytes, totalBytes: m.files.reduce((s, f) => s + f.size, 0) };
}

/** Download every Python file into the cache, reporting byte progress. */
export async function downloadEverything(onProgress: (done: number, total: number, file: string) => void): Promise<void> {
  const m = await loadManifest();
  if (!m) throw new Error('Could not read the Python manifest. Are you online?');
  const c = await caches.open(PYODIDE_CACHE);
  const total = m.files.reduce((s, f) => s + f.size, 0);
  let done = 0;
  for (const f of m.files) {
    const url = `${base()}pyodide/${f.name}`;
    if (!(await c.match(url))) {
      const r = await fetch(url);
      if (!r.ok) throw new Error(`Download failed for ${f.name} (${r.status})`);
      await c.put(url, r);
    }
    done += f.size;
    onProgress(done, total, f.name);
  }
  // make sure every lesson chunk is in the precache too
  await checkCore();
}

export function formatMB(b: number) {
  return `${(b / 1e6).toFixed(1)} MB`;
}
